  --waki-nav-shift: 2px;
  --waki-shadow-stack: 0 24px 70px var(--waki-shadow), 0 0 44px color-mix(in srgb, var(--waki-accent) 22%, transparent), inset 0 1px 0 rgba(255,255,255,.36), inset 0 -1px 0 rgba(255,255,255,.08);
  --waki-elevated-shadow-stack: 0 42px 120px var(--waki-shadow), 0 0 64px color-mix(in srgb, var(--waki-accent-2) 24%, transparent), inset 0 1px 0 rgba(255,255,255,.42), inset 0 -18px 38px color-mix(in srgb, var(--waki-accent) 8%, transparent);
  --waki-inset-shadow: inset 0 1px 0 rgba(255,255,255,.34), inset 0 0 0 1px rgba(255,255,255,.08), 0 12px 34px rgba(0,0,0,.09);
  --waki-glass-saturation: 245%;
  --waki-elevated-saturation: 275%;
  --waki-sidebar-blend: 76%;
  --waki-main-blend: 50%;
