  --waki-panel: rgba(255,255,255,.62);
  --waki-panel-2: rgba(255,255,255,.78);
  --waki-panel-3: rgba(241,245,255,.76);
  --waki-bar: rgba(255,255,255,.78);
  --waki-border: rgba(125,92,255,.22);
  --waki-border-2: rgba(45,212,191,.24);
  --waki-text: #102033;
