  --waki-bar: rgba(14,24,58,.72);
  --waki-border: rgba(103,232,249,.28);
  --waki-border-2: rgba(196,181,253,.25);
  --waki-text: #eef7ff;
  --waki-muted: #a9bad1;
  --waki-accent: #8b7cff;
  --waki-accent-2: #67e8f9;
  --waki-focus: color-mix(in srgb, #8b7cff 24%, transparent);
  --waki-shadow: rgba(0,0,0,.45);
}

body {
  background:
    radial-gradient(circle at 20% 16%, color-mix(in srgb, var(--waki-accent) 18%, transparent), transparent 28%), radial-gradient(circle at 80% 20%, color-mix(in srgb, var(--waki-accent-2) 16%, transparent), transparent 30%), linear-gradient(118deg, transparent 0 27%, color-mix(in srgb, white 12%, transparent) 39%, transparent 53%), linear-gradient(145deg, transparent 0 58%, color-mix(in srgb, var(--waki-accent) 9%, transparent) 72%, transparent 88%),
    radial-gradient(circle at 8% 10%, var(--waki-blob-1), transparent 32%),
